def heal_left(user):
    """Сколько секунд ещё действует зелье лечения (0 — не действует)."""
    return max(0.0, float(user.get("heal_until", 0) or 0) - time.time())


def fmt_pct(value):
    """10 → «10», 0.5 → «0,5»."""
    return ("%g" % value).replace(".", ",")

