def cmd_rules(msg, rest, slash):
    lines = ["📜 Правила беседы", ""]
    for i, rule in enumerate(CHAT_RULES, 1):
        lines += [f"{i}️⃣ {rule}" if i < 10 else f"🔟 {rule}", ""]
